    <script>
        const services = [
            {
                title: "Continuous Integration & Continuous Delivery (CI/CD)",
                description:
                    "Automate your entire software delivery pipeline for rapid, reliable releases. With our CI/CD pipelines, you can automate builds, parallel testing, artifact management, and zero-downtime deployments. Move features from development to production in hours, not days, all while minimizing risk and manual errors.",
                points: [
                    "Automated Code Quality Checks",
                    "Automated Versioning & Release Management",
                    "Environment Configuration as Code",
                    "Automated Rollback & Recovery Mechanisms",
                    "Parallel Test Execution and Optimization",
                    "Real-Time Monitoring & Feedback in CI/CD Pipelines",
                ],







            },
            {
                title: " Infrastructure as Code (IaC)",
                description:
                    "Standardize and automate infrastructure provisioning across cloud and on-prem environments. Utilizing powerful configuration management tools, we ensure that your infrastructure is consistent, scalable, and cost-effective. We automate resource allocation, environment replication, and scaling to support your business growth without added complexity.",
                points: [
                    "Automated Infrastructure Provisioning",
                    "Multi-Cloud Infrastructure Management",
                    "Environment Replication and Consistency",
                    "Scalable Infrastructure Deployment",
                    "Version Control for Infrastructure Changes",
                    "Continuous Monitoring and Optimization of Infrastructure",
                ],







            },
            {
                title: "DevSecOps",
                description:
                    "Integrate security throughout your DevOps lifecycle. With automated security checks, including static and dynamic code analysis, vulnerability scanning, and compliance automation, we help you maintain airtight security without compromising delivery speed. Empower your developers with self-service security tools to identify and fix vulnerabilities early.",
                points: [
                    "Automated security checks and vulnerability scanning",
                    "Static and dynamic code analysis for security",
                    "Self-service security tools for early vulnerability detection",
                ],







            },
            {
                title: "Cloud-Native Automation",
                description:
                    "Optimize your cloud infrastructure with automated scaling, monitoring, and cost management. We leverage containerization and orchestration (Kubernetes, Docker) to ensure consistent, rapid deployments across any environment. Automated backup, disaster recovery, and governance enhance resilience and compliance, ensuring your operations run smoothly.",
                points: [
                    "Automated Cloud Scaling and Load Balancing",
                    "Container Orchestration with Kubernetes and Docker",
                    "Automated Cloud Cost Management and Optimization",
                    "Continuous Monitoring and Alerting for Cloud Environments",
                    "Cloud Backup and Disaster Recovery Automation",
                    "Cloud Governance and Compliance Automation",
                ],







            },

            {
                title: "End-to-End Visibility",
                description:
                    "Gain real-time insights into every stage of your delivery pipeline with integrated monitoring, logging, and alerting systems. Proactively detect bottlenecks, security risks, and performance issues to ensure continuous improvement and faster resolution times, ultimately leading to a more efficient development cycle.",
                points: [
                    "Real-Time Performance Monitoring",
                    "Automated Log Aggregation and Analysis",
                    "Customizable Dashboards for Key Metrics",
                    "Automated Incident Detection and Alerts",
                    "Continuous Delivery Pipeline Transparency",
                    "Root Cause Analysis and Automated Reporting",
                ],



            },

        ];

        const buttonsContainer = document.getElementById("serviceButtons");
        const contentContainer = document.getElementById("serviceContent");

        function renderButtons(activeIndex = 0) {
            buttonsContainer.innerHTML = "";
            services.forEach((service, index) => {
                const isActive = index === activeIndex;
                const btnWrapper = document.createElement("div");
                btnWrapper.className = `rounded-xl ${isActive ? "pl-1 bg-gradient-to-b from-[#7C3BAF] to-[#E61C42]" : ""
                    }`;

                btnWrapper.innerHTML = `
